describe("native-gc-stats", function () {
  test("Native metrics containing gc stats", function (done) {
    nativeStats.afterGC(function (stats) {
      topLevelKeys.forEach(function (key) {
        should.exist(stats[key]);
      });

      ["before", "after", "diff"].forEach(function (topLevel) {
        entryKeys.forEach(function (entry) {
          should.exist(stats[topLevel][entry]);
        });
      });
      done();
    });

    global.gc();
  });

  test("Native metrics containing eventloop stats", function (done) {
    var eventloopStats = nativeStats.read();
    ["max", "min", "num", "sum"].forEach(function (entry) {
      expect(eventloopStats).toHaveProperty(entry);
    });
    done();
  });
});

describe("native-gc-stats", function () {
  test("Final json of site24x7-node-native-metrics", () => {
    var gcStats = GCStats.getStats();

    ["gc", "event_loop_metrics"].forEach(function (entry) {
      expect(gcStats).toHaveProperty(entry);
      if (entry == "gc" && gcStats[entry].length > 0) {
        ["max", "min", "name", "sum", "count"].forEach(function (key) {
          expect(gcStats[entry][0]).toHaveProperty(key);
        });
      } else if (entry == "event_loop_metrics:") {
        ["max", "min", "num", "sum"].forEach(function (key) {
          expect(gcStats[entry]).toHaveProperty(key);
        });
      }
    });
  });
});
